function language() { return state.profile.preferred_language === "fr" ? "fr" : "en"; }
function t(key, values = {}) { return (translations[language()]?.[key] || translations.en[key] || key).replace(/\{(\w+)\}/g, (_, name) => values[name] ?? ""); }
function escapeHtml(value = "") { return String(value).replace(/[&<>'"]/g, char => ({ "&":"&amp;", "<":"&lt;", ">":"&gt;", "'":"&#39;", '"':"&quot;" })[char]); }
function renderMarkdown(text = "") {
  const inline = value => escapeHtml(value)
    .replace(/\*\*\*([^*\n]+)\*\*\*/g, "<strong><em>$1</em></strong>")
    .replace(/\*\*([^*\n]+)\*\*/g, "<strong>$1</strong>")
    .replace(/`([^`\n]+)`/g, "<code>$1</code>");
  let pendingBullet = false;
  return String(text).split(/\r?\n/).map(line => {
    // Some providers emit a bold bullet on one line ("**•**") and the
    // actual list item on the next. Treat both lines as one list item.
    if (/^\s*(?:\*{1,3}\s*)?[•▪◦](?:\s*\*{1,3})?\s*$/.test(line)) {
      pendingBullet = true;
      return "";
    }
    const heading = line.match(/^#{1,3}\s+(.+)$/);
    const bullet = line.match(/^\s*[-*•]\s+(.+)$/);
    const boldHeading = line.match(/^\s*\*\*([^*\n]+)\*\*\s*$/);
    if (heading) return `<h3>${inline(heading[1])}</h3>`;
    if (boldHeading) return `<h3>${inline(boldHeading[1])}</h3>`;
    if (bullet) return `<div class="markdown-bullet"><span>•</span><span>${inline(bullet[1])}</span></div>`;
    if (pendingBullet && line.trim()) {
      pendingBullet = false;
      return `<div class="markdown-bullet"><span>•</span><span>${inline(line)}</span></div>`;
    }
    return line.trim() ? `<p>${inline(line)}</p>` : `<div class="markdown-space"></div>`;
  }).join("");
}
function resourceForCitation(identifier) { const resources = state.project?.resource_library || []; return resources.find(resource => resource.id === identifier || resource.id.startsWith(identifier)); }
function sourceLocationLabel(resource) { return resource?.file_type === "pptx" ? (state.profile.preferred_language === "fr" ? "diapo." : "slide") : "p."; }
function sourceWarning(resource) { return resource?.file_type === "pptx" ? "Source: user-supplied presentation — primary reference unavailable." : ""; }
function citationTitle(resource) { return [resource?.title || resource?.filename || "", sourceWarning(resource)].filter(Boolean).join(" · "); }
function formatCitationsForDisplay(text = "") { const verifiedPattern = /\[\[cite:\s*([^|\]\s]+)\s*\|\s*p\.\s*([0-9]+)\s*\|\s*[^\]]+?\s*\]\]/gi, citationPattern = /\[([0-9a-zA-Z][0-9a-zA-Z-]{3,})\s*,\s*p\.\s*([0-9]+(?:\s*,\s*[0-9]+)*)\]/g; const identifierPattern = /(?<![0-9a-fA-F])([0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}|[0-9a-fA-F]{8})(?![0-9a-fA-F])/g; const verified = String(text).replace(verifiedPattern, (match, identifier, page) => { const resource = resourceForCitation(identifier); return resource ? `[${citationTitle(resource)}, ${sourceLocationLabel(resource)} ${page}]` : match; }); const cited = verified.replace(citationPattern, (match, identifier, pages) => { const resource = resourceForCitation(identifier); return resource ? `[${citationTitle(resource)}, ${sourceLocationLabel(resource)} ${pages}]` : match; }); return cited.replace(identifierPattern, (match, identifier) => { const resource = resourceForCitation(identifier); return resource ? citationTitle(resource) : match; }); }
function technicalCitationDetails(text = "") { const verifiedPattern = /\[\[cite:\s*([^|\]\s]+)\s*\|\s*p\.\s*([0-9]+)\s*\|\s*[^\]]+?\s*\]\]/gi, citationPattern = /\[([0-9a-zA-Z][0-9a-zA-Z-]{3,})\s*,\s*p\.\s*([0-9]+(?:\s*,\s*[0-9]+)*)\]/g, identifierPattern = /(?<![0-9a-fA-F])([0-9a-fA-F]{8}(?:-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}|[0-9a-fA-F]{8})(?![0-9a-fA-F])/g, details = [], seen = new Set(); const add = (identifier, pages = "") => { const resource = resourceForCitation(identifier); if (!resource || seen.has(`${resource.id}:${pages}`)) return; seen.add(`${resource.id}:${pages}`); details.push({resource, pages}); }; for (const match of String(text).matchAll(verifiedPattern)) add(match[1], match[2]); for (const match of String(text).matchAll(citationPattern)) add(match[1], match[2]); for (const match of String(text).matchAll(identifierPattern)) add(match[1]); if (!details.length) return ""; return `<details class="citation-details"><summary>${escapeHtml(t("technicalCitationDetails"))}</summary>${details.map(({resource, pages}) => `<div><strong>${escapeHtml(citationTitle(resource))}</strong>${pages ? ` · ${sourceLocationLabel(resource)} ${escapeHtml(pages)}` : ""}<code>${escapeHtml(t("technicalSourceId"))}: ${escapeHtml(resource.id)}</code></div>`).join("")}</details>`; }
function renderedModelMessage(text) { return `${renderMarkdown(formatCitationsForDisplay(text))}${technicalCitationDetails(text)}`; }
function endpoint(path) { return path.split("/").map(encodeURIComponent).join("/"); }
function setLoading(value) { $("#loading").hidden = !value; }
function notify(message, isError = false) { const node = $("#notice"); node.textContent = message; node.hidden = !message; node.className = `notice${isError ? " error" : ""}`; }
