function applyRoleEmblem() { const asclepius = `<svg class="role-icon" viewBox="0 0 32 32" aria-hidden="true"><path d="M16 3v26M12 6c-5 1-5 7-1 8 6 1 6-6 1-4-4 2-1 8 4 8 5 0 7-6 3-10-2-2-5-2-7-1"/><path d="M12 3h8"/></svg>`; const emblems = {professor_medicine:asclepius, assistant_professor:asclepius, specialist_physician:asclepius, resident_physician:asclepius, veterinarian:`<svg class="role-icon" viewBox="0 0 40 32" aria-hidden="true"><path d="M3 4 12 28 21 4"/><path d="M28 3v26M25 7c-4 1-4 6-1 7 5 1 5-5 1-4-3 1-1 6 3 6 4 0 6-5 3-8-2-2-5-2-6-1"/><path d="M24 3h8"/></svg>`, biologist:`<svg class="role-icon" viewBox="0 0 32 32" aria-hidden="true"><path d="M8 4c12 7 4 17 16 24M24 4C12 11 20 21 8 28M10 8h12M8 16h16M10 24h12"/></svg>`, pharmacist:`<svg class="role-icon" viewBox="0 0 32 32" aria-hidden="true"><path d="M6 20h20M9 20c1 6 13 6 14 0M12 25h8M17 5c7-2 9 6 4 8-5 2-7-4-3-6 3-2 6 3 2 6-3 3-8 0-8-4"/><path d="M13 14h8l-2 6h-4z"/></svg>`}; const emblem = $("#role-emblem"); if (!emblem) return; emblem.innerHTML = emblems[state.profile.professional_role] || asclepius; emblem.setAttribute("aria-label", t(`role_${state.profile.professional_role}`)); }
function applyLanguage() {
  const currentLanguage = language();
  document.documentElement.lang = currentLanguage;
  document.documentElement.dir = "ltr";
  document.querySelectorAll("[data-i18n]").forEach(node => { node.textContent = t(node.dataset.i18n); });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(node => { node.placeholder = t(node.dataset.i18nPlaceholder); });
  document.querySelectorAll("[data-i18n-aria-label]").forEach(node => { node.setAttribute("aria-label", t(node.dataset.i18nAriaLabel)); });
  $("#create-project").title = t("newProject");
  $("#auth-language").value = currentLanguage;
  $("#user-language").value = currentLanguage;
  applyRoleEmblem();
  if (state.project) render();
}
async function api(path, options = {}) {
  const {showLoading = true, public: isPublic = false, ...fetchOptions} = options;
  if (showLoading) setLoading(true);
  try {
    const headers = new Headers(fetchOptions.headers || {});
    if (state.token && !isPublic) headers.set("Authorization", `Bearer ${state.token}`);
    const response = await fetch(path, {...fetchOptions, headers});
    if (!response.ok) { const payload = await response.json().catch(() => ({})); const detail = payload.detail; const message = typeof detail === "string" ? detail : detail?.message; const error = new Error(message || t("unexpectedError")); error.code = typeof detail === "object" ? detail?.code : null; error.detail = typeof detail === "object" ? detail : {}; error.status = response.status; throw error; }
    return response;
  } finally { if (showLoading) setLoading(false); }
}
function projectPath(suffix = "") { return `/projects/${endpoint(state.userId)}/${endpoint(state.projectId)}${suffix}`; }
function currentPresentation() { return state.project?.presentation; }
function currentProjectName() { return state.projects.find(project => project.id === state.projectId)?.name || t("project"); }
function formattedMessage(content) { if (typeof content === "string") return content; if (Array.isArray(content)) return content.map(block => block?.text || "").join("\n"); return ""; }

async function loadProjects() { const response = await api(`/users/${endpoint(state.userId)}/dashboard`); state.dashboard = await response.json(); state.projects = state.dashboard.projects; const libraryResponse = await api(`/users/${endpoint(state.userId)}/resources`); state.ownerLibrary = (await libraryResponse.json()).resources; const select = $("#project-id"); if (state.projectId && !state.projects.some(project => project.id === state.projectId)) state.projectId = ""; select.innerHTML = state.projects.map(project => `<option value="${escapeHtml(project.id)}">${escapeHtml(project.name)}</option>`).join(""); select.value = state.projectId; }
async function loadTemplates() { const response = await api(`/users/${endpoint(state.userId)}/templates`); state.templates = (await response.json()).templates; }
async function openProject(projectName = null) { closeOcrReview(); state.projectId = state.projectId || $("#project-id").value; state.workspace = localStorage.getItem(`hpa_workspace_${state.userId}_${state.projectId}`) || "presentation"; const response = await api("/projects", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({user_id:state.userId, project_id:state.projectId, project_name:projectName})}); state.project = await response.json(); render(); }
async function createProject() { const projectName = $("#new-project-name").value.trim(); if (!projectName) return notify(t("projectNameRequired"), true); state.projectId = `project-${crypto.randomUUID()}`; try { await openProject(projectName); await loadProjects(); $("#project-id").value = state.projectId; $("#new-project-name").value = ""; render(); notify(t("projectCreated", {name:projectName})); } catch (error) { notify(error.message, true); } }
