function saveProjectResponse(payload) { state.project = payload; render(); void refreshDashboard(); }
async function refreshDashboard() { try { await loadProjects(); render(); } catch (error) { /* The saved Project response remains authoritative if this read fails. */ } }
async function waitForJob(job) {
  let current = job;
  while (current.status === "queued" || current.status === "running") {
    await new Promise(resolve => window.setTimeout(resolve, 450));
    const response = await api(`/api/v1/jobs/${endpoint(state.userId)}/${endpoint(current.job_id)}`, {showLoading:false});
    current = await response.json();
  }
  if (current.status === "cancelled") throw new Error(t("sourceWorkCancelled"));
  if (current.status === "failed") throw new Error(current.error || t("unexpectedError"));
  return current;
}

async function authenticate(path) {
  const userId = $("#auth-user-id").value.trim(), password = $("#auth-password").value, error = $("#auth-error");
  error.hidden = true;
  const body = {user_id:userId, password};
  if (path.endsWith("/register")) { body.professional_role = "professor_medicine"; body.preferred_language = $("#auth-language").value; }
  try { const response = await api(path, {public:true, method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(body)}); const payload = await response.json(); state.userId = payload.user_id; state.token = payload.token; state.profile = payload.profile; sessionStorage.setItem("hpa_user_id", state.userId); sessionStorage.setItem("hpa_token", state.token); await startWorkspace(); } catch (exception) { error.textContent = exception.message; error.hidden = false; }
}
async function updateProfile() {
  const profile = {professional_role:state.profile.professional_role, preferred_language:$("#user-language").value};
  state.profile = profile; applyLanguage();
  try { const response = await api(`/users/${endpoint(state.userId)}/profile`, {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify(profile)}); state.profile = (await response.json()).profile; applyLanguage(); } catch (error) { notify(error.message, true); }
}
async function startWorkspace() {
  $("#user-id").value = state.userId;
  $("#user-display").textContent = state.userId;
  const profileResponse = await api(`/users/${endpoint(state.userId)}/profile`); state.profile = (await profileResponse.json()).profile; applyLanguage();
  await loadTemplates();
  await loadProjects();
  if (!state.projects.length) { state.projectId = "project-1"; await openProject(t("firstProject")); await loadProjects(); }
  else { const lastProject = localStorage.getItem(`hpa_project_${state.userId}`); state.projectId = state.projects.some(project => project.id === lastProject) ? lastProject : state.projects[0].id; await openProject(); }
  localStorage.setItem(`hpa_project_${state.userId}`, state.projectId); $("#auth-screen").hidden = true;
}
function logout() { closeOcrReview(); sessionStorage.removeItem("hpa_user_id"); sessionStorage.removeItem("hpa_token"); window.location.reload(); }
async function deleteProject() { if (!state.projectId || !window.confirm(t("deleteProjectConfirm"))) return; try { const deletion = await api(`/projects/${endpoint(state.userId)}/${endpoint(state.projectId)}`, {method:"DELETE"}); if (deletion.status === 202) window.alert(t("sourceCleanupPending")); state.project = null; state.projectId = ""; await loadProjects(); if (state.projects.length) { state.projectId = state.projects[0].id; await openProject(); } else { render(); notify(t("projectDeleted")); } } catch (error) { notify(error.message, true); } }
async function resumeProject(projectId) { if (!state.projects.some(project => project.id === projectId)) return; state.projectId = projectId; localStorage.setItem(`hpa_project_${state.userId}`, state.projectId); $("#project-id").value = projectId; try { await openProject(); } catch (error) { notify(error.message, true); } }
async function deleteUser() { if (!window.confirm(t("deleteAccountConfirm"))) return; try { const deletion = await api(`/users/${endpoint(state.userId)}`, {method:"DELETE"}); if (deletion.status === 202) window.alert(t("sourceCleanupPending")); logout(); } catch (error) { notify(error.message, true); } }

function renderMessages(messages = []) { const node = $("#chat-messages"); const visibleMessages = [...messages]; if (state.chatPending) visibleMessages.push({role:"assistant typing", text:t("assistantThinking"), typing:true}); if (!visibleMessages.length) { node.innerHTML = `<div class="empty-chat">${escapeHtml(t("chatEmpty"))}</div>`; return; } node.innerHTML = visibleMessages.map(message => message.typing ? `<div class="message ${message.role}" aria-live="polite"><span class="typing-label">${escapeHtml(message.text)}</span><span class="typing-dots"><i></i><i></i><i></i></span></div>` : `<div class="message ${message.role} markdown-content">${message.role === "assistant" ? renderedModelMessage(message.text) : renderMarkdown(message.text)}</div>`).join(""); node.scrollTop = node.scrollHeight; }
function renderResourceMessages(messages = []) {
  const node = $("#resource-chat-messages");
  if (!node) return;
  const visible = [...messages];
  const last = visible[visible.length - 1];
  if (state.resourcePendingQuestion && !(last?.role === "user" && last.text === state.resourcePendingQuestion)) {
    visible.push({role:"user", text:state.resourcePendingQuestion});
  }
  if (state.resourceOperation === "discussion") {
    visible.push({role:"assistant typing", text:t("assistantThinking"), typing:true});
  }
  if (!visible.length) {
    node.innerHTML = `<div class="empty-chat">${escapeHtml(t("resourceChatEmpty"))}</div>`;
    return;
  }
  node.innerHTML = visible.map(message => message.typing
    ? `<div class="message ${message.role}" aria-live="polite"><span class="typing-label">${escapeHtml(message.text)}</span><span class="typing-dots"><i></i><i></i><i></i></span></div>`
    : `<div class="message ${message.role} markdown-content">${message.role === "assistant" ? renderedModelMessage(message.text) : renderMarkdown(message.text)}</div>`
  ).join("");
  node.scrollTop = node.scrollHeight;
}
function setWorkspace(workspace) { state.workspace = ["presentation", "resources", "analysis"].includes(workspace) ? workspace : "presentation"; if (state.userId && state.projectId) localStorage.setItem(`hpa_workspace_${state.userId}_${state.projectId}`, state.workspace); render(); }
function renderWorkspace() { $("#presentation-workspace").hidden = state.workspace !== "presentation"; $("#resources-workspace").hidden = state.workspace !== "resources"; $("#analysis-workspace").hidden = state.workspace !== "analysis"; document.querySelectorAll(".workspace-tab").forEach(button => { const active = button.dataset.workspace === state.workspace; button.classList.toggle("active", active); button.setAttribute("aria-selected", String(active)); }); }
function formatDashboardTime(value) { if (!value) return "—"; const parsed = new Date(`${String(value).replace(" ", "T")}Z`); return Number.isNaN(parsed.getTime()) ? String(value) : new Intl.DateTimeFormat(language(), {dateStyle:"medium", timeStyle:"short"}).format(parsed); }
function dashboardWorkflow(status) { return t(`workflow_${status}`) === `workflow_${status}` ? String(status || "").replaceAll("_", " ") : t(`workflow_${status}`); }
function dashboardEvent(event) { return String(event || "").replaceAll("_", " ").toLowerCase(); }
