    const recent = project.recent_actions?.length ? project.recent_actions.map(action => `<li>${escapeHtml(dashboardEvent(action.event_type))} · ${escapeHtml(formatDashboardTime(action.created_at))}</li>`).join("") : `<li>${escapeHtml(t("noRecentActions"))}</li>`;
    const contextLine = context.topic ? `${context.topic} · ${context.audience || "—"} · ${context.duration_minutes || "—"} min · ${context.target_slide_count || "—"} slides` : t("contextNotCompleted");
    const purpose = context.objective || "—", instructions = context.special_instructions || t("noInstructions");
