function generatedSafetyDetails(slide, index) { const claims = [...(slide.claims || []), ...(slide.speaker_note?.claims || [])], missing = claims.filter(claim => claim.missing_value), groups = Object.groupBy ? Object.groupBy(claims.filter(claim => claim.conflict_group_id), claim => claim.conflict_group_id) : claims.filter(claim => claim.conflict_group_id).reduce((all, claim) => ((all[claim.conflict_group_id] ||= []).push(claim), all), {}), conflicts = Object.entries(groups); return `${missing.map(claim => `<p class="preview-note"><strong>${escapeHtml(t("missingValue"))}:</strong> ${escapeHtml(claim.text)} · ${escapeHtml(claim.uncertainty || "")}</p>`).join("")}${conflicts.map(([id, positions]) => `<details open class="evidence-detail"><summary>${escapeHtml(t("visibleConflict"))} · ${escapeHtml(id)}</summary>${positions.map(claim => `<p><strong>${escapeHtml(claim.source_position || "")}</strong> — ${escapeHtml(claim.text)}${claim.value ? ` · ${escapeHtml(claim.value)} ${escapeHtml(claim.unit || "")}` : ""}</p>`).join("")}</details>`).join("")}${slide.speaker_note ? `<details class="evidence-detail"><summary>${escapeHtml(t("speakerNoteEvidence"))}</summary><p>${escapeHtml(slide.speaker_note.text)}</p>${claimEvidenceDetails({claims:slide.speaker_note.claims,evidence_links:slide.speaker_note.evidence_links})}<small>${escapeHtml(slide.speaker_note.is_approved ? t("approved") : t("speakerNotePending"))}</small><div class="action-row"><button class="outline-button" data-note-review="approve" data-index="${index}">Approve notes</button><button class="outline-button" data-note-review="reject" data-index="${index}">Reject notes</button></div></details>` : ""}`; }
function slideEditor(slide, index) { return `<details class="content-editor"><summary>${escapeHtml(t("editContent"))}</summary><label>${escapeHtml(t("source"))}</label><input data-edit-field="title" value="${escapeHtml(slide.title)}" /><label>${escapeHtml(t("objective"))}</label><textarea data-edit-field="objective">${escapeHtml(slide.objective || "")}</textarea><label>${escapeHtml(t("keyMessagesPerLine"))}</label><textarea data-edit-field="key_messages">${escapeHtml((slide.key_messages || []).join("\n"))}</textarea><label>${escapeHtml(t("slideContent"))}</label><textarea data-edit-field="content">${escapeHtml(slide.content || "")}</textarea><label>${escapeHtml(t("speakerNotes"))}</label><textarea data-edit-field="speaker_notes">${escapeHtml(slide.speaker_notes || "")}</textarea><label>${escapeHtml(t("contentOrigin"))}</label>${originOptions(slide.content_origin)}<label>Content classification</label><select data-edit-field="content_classification"><option value="medical" ${slide.content_classification !== "nonmedical" ? "selected" : ""}>Medical</option><option value="nonmedical" ${slide.content_classification === "nonmedical" ? "selected" : ""}>Nonmedical</option></select><div class="action-row"><button class="outline-button" data-edit="slide" data-index="${index}">${escapeHtml(t("saveUserEdit"))}</button><button class="outline-button" data-edit="reformulation" data-index="${index}">Save reformulation</button></div></details>`; }
function renderReview(presentation) { const area = $("#review-area"); if (!presentation) { area.innerHTML = ""; return; } const blueprint = presentation.blueprint, pending = state.generationOperation ? `<div class="resource-operation" aria-live="polite"><span class="inline-spinner"></span>${escapeHtml(t("processing"))}</div>` : "", disabled = state.generationOperation ? "disabled" : ""; const blueprintHtml = blueprint ? `<section class="review-section"><div class="review-head"><div><p class="eyebrow">${escapeHtml(t("humanReview"))}</p><h2>Blueprint</h2></div><button class="outline-button" data-action="blueprint-regenerate" ${disabled}>${escapeHtml(t("regenerateComments"))}</button></div>${pending}<div class="review-grid">${blueprint.slides.map((item,index) => `<article class="review-item ${item.is_validated ? "approved" : ""}"><h3>${item.slide_number}. ${escapeHtml(item.title)}</h3><span class="pill">${escapeHtml((item.slide_role || "content").replace("_", " "))}</span>${originBadge(item)}<p><strong>${escapeHtml(t("objective"))}:</strong> ${escapeHtml(item.objective)}<br><strong>${escapeHtml(t("keyMessage"))}:</strong> ${escapeHtml(item.key_message)}<br><strong>${escapeHtml(t("plannedSources"))}:</strong> ${escapeHtml((item.supporting_source_ids || []).join(", "))}<br><strong>${escapeHtml(t("plannedVisual"))}:</strong> ${escapeHtml(item.planned_visual || "")}</p>${blueprintEditor(item, index)}<textarea data-comment="blueprint" data-index="${index}" placeholder="${escapeHtml(t("reviewerComment"))}" ${disabled}>${escapeHtml(item.reviewer_comments || "")}</textarea>${itemActions("blueprint", index, item.is_validated)}</article>`).join("")}</div></section>` : ""; const slidesHtml = presentation.slides?.length ? `<section class="review-section"><div class="review-head"><div><p class="eyebrow">${escapeHtml(t("humanReview"))}</p><h2>${escapeHtml(t("slides"))}</h2></div></div><div class="review-grid">${presentation.slides.map((slide,index) => `<article class="review-item ${slide.is_validated ? "approved" : ""}"><h3>${index+1}. ${escapeHtml(slide.title)}</h3>${originBadge(slide)}<p>${escapeHtml(slide.content || slide.key_messages?.join(" · ") || "")}</p>${slide.content_origin === "ai_generated" ? (claimEvidenceDetails(slide) || evidenceDetails(slide.reference_details)) + generatedSafetyDetails(slide, index) : ""}${slide.authorship_warning ? `<p class="preview-note">${escapeHtml(slide.authorship_warning)}</p>` : ""}${(slide.content_origin === "ai_generated" ? [] : slide.source_warnings || []).map(w => `<p class="preview-note">${escapeHtml(w)}</p>`).join("")}${slideEditor(slide, index)}<textarea data-comment="slide" data-index="${index}" placeholder="${escapeHtml(t("reviewerComment"))}" ${disabled}>${escapeHtml(slide.reviewer_comments || "")}</textarea>${itemActions("slide", index, slide.is_validated)}</article>`).join("")}</div></section>` : ""; area.innerHTML = blueprintHtml + slidesHtml; }

function previewLabel(presentation, english, french, arabic) {
  const language = presentation?.context?.language;
  return language === "French" ? french : language === "Arabic" ? arabic : english;
}

function presentationPreviewPages(presentation) {
  if (!presentation?.slides?.length) return [];
  const context = presentation.context || {};
  const details = [
    [context.presenter_name, context.presenter_title].filter(Boolean).join(" · "),
    context.organization,
    context.event_name,
    [context.venue, context.presentation_date].filter(Boolean).join(" · "),
  ].filter(Boolean);
  const pages = [{
    kind: "cover",
    title: presentation.title,
    objective: context.objective,
    details,
    meta: `${context.duration_minutes || ""} min · ${context.audience || ""}`,
  }];
  if (presentation.agenda?.items?.length) {
    pages.push({
      kind: "agenda",
      title: previewLabel(presentation, "Agenda", "Agenda", "جدول الأعمال"),
      items: presentation.agenda.items,
    });
  }
  presentation.slides.forEach(slide => pages.push({
    sourceWarnings: slide.source_warnings || [],
    kind: "content",
    title: slide.title,
    items: slide.key_messages?.length ? slide.key_messages : [slide.content].filter(Boolean),
    origin: slide.content_origin || "ai_generated",
    references: slide.content_origin === "ai_generated" && slide.evidence_verified
      ? (slide.evidence_links || []).filter(link => link.provenance_verified && link.semantic_review === "approved").map(link => ({title:link.resource_title, resource_id:link.resource_id, page:link.location_number, evidence_excerpt:link.exact_passage}))
      : [],
  }));
  const resources = presentation.resources || [];
  const batches = Math.ceil(resources.length / 4);
  for (let index = 0; index < resources.length; index += 4) {
    pages.push({
      kind: "resources",
      title: previewLabel(presentation, "Resources and validation", "Ressources et validation", "المصادر والاعتماد"),
      resources: resources.slice(index, index + 4),
      batch: index / 4 + 1,
      batches,
      origins: {
        ai_generated: presentation.slides.filter(slide => slide.content_origin === "ai_generated").length,
        user_edited: presentation.slides.filter(slide => slide.content_origin === "user_edited").length,
        user_authored: presentation.slides.filter(slide => slide.content_origin === "user_authored").length,
      },
    });
  }
  return pages;
}

function previewOriginLabel(origin) {
  return t(origin === "user_authored" ? "userAuthored" : origin === "user_edited" ? "userEdited" : "aiGenerated");
}

function previewPageContent(page) {
  if (page.kind === "cover") {
    return `<span class="deck-kicker">HEALTHCARE PRESENTATION</span><h3>${escapeHtml(page.title)}</h3><p class="deck-objective">${escapeHtml(page.objective || "")}</p><div class="deck-details">${page.details.map(item => `<span>${escapeHtml(item)}</span>`).join("")}</div><small>${escapeHtml(page.meta)}</small>`;
  }
  if (page.kind === "agenda") {
    return `<h3>${escapeHtml(page.title)}</h3><ol class="deck-agenda">${page.items.map(item => `<li>${escapeHtml(item)}</li>`).join("")}</ol>`;
  }
  if (page.kind === "resources") {
    const title = `${page.title}${page.batches > 1 ? ` (${page.batch}/${page.batches})` : ""}`;
    const provenance = page.batch === 1
      ? `<p class="deck-provenance">${escapeHtml(t("contentProvenance"))}: ${page.origins.ai_generated} ${escapeHtml(t("aiGenerated"))}, ${page.origins.user_edited} ${escapeHtml(t("userEdited"))}, ${page.origins.user_authored} ${escapeHtml(t("userAuthored"))}.</p>`
      : "";
    return `<h3>${escapeHtml(title)}</h3>${page.batch === 1 ? `<p class="deck-objective">${escapeHtml(t("resourcesValidatedByUser"))}</p>` : ""}${provenance}<div class="deck-resources">${page.resources.map(resource => `<div><strong>${escapeHtml(resource.title || resource.filename || t("source"))}</strong>${resource.source ? `<span>${escapeHtml(resource.source)}</span>` : ""}${sourceWarning(resource) ? `<span>${escapeHtml(sourceWarning(resource))}</span>` : ""}<small>ID: ${escapeHtml(resource.id || "")}</small></div>`).join("")}</div>`;
  }
  const evidence = page.references.length
    ? `<div class="deck-evidence">${page.references.map(reference => `<span>${escapeHtml(reference.title || t("source"))} · ${sourceLocationLabel(resourceForCitation(reference.resource_id))} ${escapeHtml(String(reference.page || ""))}</span>`).join("")}</div>`
    : `<div class="deck-authorship">${escapeHtml(previewOriginLabel(page.origin))} · ${escapeHtml(t("humanReview"))}</div>`;
  return `<h3>${escapeHtml(page.title)}</h3><ul class="deck-bullets">${page.items.map(item => `<li>${escapeHtml(item)}</li>`).join("")}</ul>${evidence}${(page.sourceWarnings || []).map(w => `<p class="preview-note">${escapeHtml(w)}</p>`).join("")}`;
}

function renderPresentationPreview(presentation) {
  const area = $("#presentation-preview-area");
  if (!area) return;
  const pages = presentationPreviewPages(presentation);
  if (!pages.length) {
    area.innerHTML = "";
    return;
  }
  state.previewIndex = Math.max(0, Math.min(state.previewIndex, pages.length - 1));
  const page = pages[state.previewIndex];
  const theme = presentation.theme || "clinical";
  area.innerHTML = `<section class="review-section presentation-preview"><div class="review-head"><div><p class="eyebrow">PowerPoint</p><h2>${escapeHtml(t("presentationPreview"))}</h2></div><span class="pill">${escapeHtml(t("previewSlide", {current: state.previewIndex + 1, total: pages.length}))}</span></div><p class="muted">${escapeHtml(t("presentationPreviewHint"))}</p>${presentation.custom_template_id ? `<p class="preview-note">${escapeHtml(t("customTemplatePreviewNote"))}</p>` : ""}<div class="deck-preview ${escapeHtml(theme)} ${escapeHtml(page.kind)}">${previewPageContent(page)}<footer>HPA · ${escapeHtml(previewOriginLabel(page.origin || "ai_generated"))}</footer></div><div class="preview-controls"><button class="outline-button" data-action="preview-previous" ${state.previewIndex === 0 ? "disabled" : ""}>← ${escapeHtml(t("previewPrevious"))}</button><button class="outline-button" data-action="preview-next" ${state.previewIndex === pages.length - 1 ? "disabled" : ""}>${escapeHtml(t("previewNext"))} →</button></div></section>`;
}

function setChatPending(value) { state.chatPending = value; $("#chat-input").disabled = value; $("#chat-form button").disabled = value; $("#chat-form").setAttribute("aria-busy", String(value)); }
async function sendChat(event) { event.preventDefault(); if (state.chatPending) return; const input = $("#chat-input"), message = input.value.trim(); if (!message) return; setChatPending(true); renderMessages([...(state.project?.messages || []), {role:"user", text:message}]); input.value = ""; try { const response = await api("/api/v1/conversations/jobs", {showLoading:false, method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({message, user_id:state.userId, project_id:state.projectId})}); await waitForJob(await response.json()); setChatPending(false); await refreshProject(false); } catch (error) { setChatPending(false); notify(error.message, true); await refreshProject(false); } }
async function uploadResource({resourceDeclaration = null} = {}) { if (state.resourceUploadPending) return; const file = state.pendingContactFile || $("#pdf-file").files[0]; if (!file) return; if (!state.project?.prototype_declaration) { state.declarationPrompt = true; render(); return; } if (file.size > 20*1024*1024) return notify(t("resourceLimit"), true); const form = new FormData(); form.append("file", file); if (resourceDeclaration) form.append("resource_declaration", resourceDeclaration); state.resourceUploadPending = true; $("#upload-resource").disabled = true; $("#confirm-contact-review").disabled = true; try { const response = await api(`/resources/${endpoint(state.userId)}/${endpoint(state.projectId)}`, {method:"POST", body:form}); const payload = await response.json(); state.pendingContactFile = null; $("#contact-review-modal").hidden = true; notify(t("resourceAdded", {name:payload.filename})); await refreshProject(); } catch (error) { if (error.code === "RESOURCE_USER_CONTEXT_REQUIRED" || error.code === "INSTITUTIONAL_CONTACT_REVIEW_REQUIRED") { state.pendingContactFile = file; $("#contact-review-modal").hidden = false; return; } notify(error.message, true); } finally { state.resourceUploadPending = false; $("#upload-resource").disabled = !$("#pdf-file").files[0]; $("#confirm-contact-review").disabled = false; } }
async function analyzeResources() { if (state.resourceOperation) return; state.resourceOperation = "analysis"; render(); try { const response = await api(`/api/v1/resources/${endpoint(state.userId)}/${endpoint(state.projectId)}/overview/jobs`, {showLoading:false, method:"POST"}); await waitForJob(await response.json()); await refreshProject(false); notify(t("analysisGenerated")); } catch (error) { notify(error.message, true); } finally { state.resourceOperation = null; render(); } }
async function discussResources() {
  const question = $("#resource-question")?.value.trim();
  if (!question || state.resourceOperation) return;
  state.resourceOperation = "discussion";
  state.resourcePendingQuestion = question;
  render();
  try {
    const response = await api(`/api/v1/resources/${endpoint(state.userId)}/${endpoint(state.projectId)}/discussion/jobs`, {showLoading:false, method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({question})});
    await waitForJob(await response.json());
    state.resourcePendingQuestion = "";
    await refreshProject(false);
  } catch (error) {
    notify(error.message, true);
    await refreshProject(false);
  } finally {
    state.resourceOperation = null;
    state.resourcePendingQuestion = "";
    render();
  }
}
let ocrReview = null;
function closeOcrReview() {
  closeAssetReview();
  if (ocrReview) ocrReview.urls.forEach(url => URL.revokeObjectURL(url));
  ocrReview = null;
  const panel = $("#ocr-review-panel"); panel.innerHTML = ""; panel.hidden = true;
}
async function openOcrReview(resourceId) {
  closeOcrReview();
  const fr = state.profile.preferred_language === "fr", user = state.userId;
  const path = `/users/${endpoint(user)}/resources/${endpoint(resourceId)}`;
  const session = {resourceId, user, path, urls:[], revision:0}; ocrReview = session;
  try {
    const data = await (await api(`${path}/ocr-review`)).json();
    if (ocrReview !== session) return;
    session.revision = data.revision;
    const panel = $("#ocr-review-panel"); panel.hidden = false;
    panel.innerHTML = `<h3>${fr ? "Vérifier les extractions" : "Review extractions"}</h3><p>${fr ? "Comparez chaque valeur à son original, corrigez si nécessaire puis cochez sa confirmation. Cette action ne valide pas scientifiquement la source." : "Compare each value with its original, correct it if needed, then confirm it. This does not scientifically validate the source."}</p>` + data.regions.map(region => `<div class="ocr-review-row"><div><small>p. ${region.page}</small><img data-ocr-image="${region.index}" alt="${fr ? "Région originale" : "Original region"}" /></div><div><label>${fr ? "Valeur OCR initiale" : "Original OCR value"}</label><p>${escapeHtml(region.extracted_value)}</p><label>${fr ? "Valeur à conserver" : "Value to retain"}<textarea data-ocr-value="${region.index}" maxlength="10000">${escapeHtml(region.value)}</textarea></label><label><input type="checkbox" data-ocr-confirm="${region.index}" /> ${fr ? "J’ai vérifié cette valeur sur l’original" : "I checked this value against the original"}</label>${region.review ? `<small>${escapeHtml(region.review.actor)} · ${escapeHtml(region.review.confirmed_at)} · ${escapeHtml(region.review.provenance)}</small>` : ""}</div></div>`).join("") + `<button data-ocr-save disabled>${fr ? "Confirmer les valeurs vérifiées" : "Confirm reviewed values"}</button> <button data-ocr-close>${fr ? "Fermer" : "Close"}</button>`;
    for (const region of data.regions) {
      const blob = await (await api(`${path}/ocr-regions/${region.index}`, {showLoading:false})).blob();
      if (ocrReview !== session) return;
      const url = URL.createObjectURL(blob); session.urls.push(url);
      panel.querySelector(`[data-ocr-image="${region.index}"]`).src = url;
    }
    session.imagesReady = true;
    panel.querySelector('[data-ocr-save]').disabled = ![...panel.querySelectorAll('[data-ocr-confirm]')].every(box => box.checked);
  } catch (error) { if (ocrReview === session) closeOcrReview(); notify(error.message, true); }
}
$("#ocr-review-panel").addEventListener("input", event => {
  const panel = $("#ocr-review-panel");
  if (event.target.matches('[data-ocr-value]')) panel.querySelector(`[data-ocr-confirm="${event.target.dataset.ocrValue}"]`).checked = false;
  const button = panel.querySelector('[data-ocr-save]');
  if (button) button.disabled = !ocrReview?.imagesReady || ![...panel.querySelectorAll('[data-ocr-confirm]')].every(box => box.checked);
});
$("#ocr-review-panel").addEventListener("click", async event => {
  if (event.target.matches('[data-ocr-close]')) return closeOcrReview();
  if (!event.target.matches('[data-ocr-save]') || !ocrReview) return;
  const session = ocrReview, panel = $("#ocr-review-panel");
  if (session.user !== state.userId) return closeOcrReview();
  event.target.disabled = true;
  try {
    await api(`${session.path}/ocr-review`, {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({expected_revision:session.revision, values:[...panel.querySelectorAll('[data-ocr-value]')].map(input => input.value), confirmed_regions:[...panel.querySelectorAll('[data-ocr-confirm]')].filter(box => box.checked).map(box => Number(box.dataset.ocrConfirm))})});
    closeOcrReview(); await loadProjects(); await refreshProject(); notify(t("validationSaved"));
  } catch (error) { notify(error.message, true); if (ocrReview === session) event.target.disabled = false; }
});

async function resourceAction(resourceId, action) {
  if (action === "asset-review") return openAssetReview(resourceId);
  if ((action === "delete" || action === "permanent") && assetReview?.resourceId === resourceId) closeAssetReview();
  if (action === "ocr-review") return openOcrReview(resourceId);
  if ((action === "delete" || action === "permanent") && !window.confirm(t(action === "permanent" ? "deleteSourceConfirm" : "removeResourceConfirm"))) return;
  if ((action === "delete" || action === "permanent") && ocrReview?.resourceId === resourceId) closeOcrReview();
  const path = action === "permanent" ? `/users/${endpoint(state.userId)}/resources/${endpoint(resourceId)}` : action === "add" ? projectPath(`/library/${endpoint(resourceId)}`) : projectPath(`/resources/${endpoint(resourceId)}${action === "attach" || action === "detach" ? "/attach" : ""}`);
  try {
    const response = await api(path, {method:action === "attach" || action === "add" ? "POST" : "DELETE"});
    const result = await response.json();
    if (action === "permanent") { await loadTemplates(); await loadProjects(); if (state.projectId) await openProject(); else render(); if (result.cleanup_pending) notify(t("sourceCleanupPending"), true); }
    else saveProjectResponse(result);
    $("#pdf-file").value = ""; $("#file-name").textContent = t("maxSize");
  } catch (error) { notify(error.message, true); }
}
async function setupPresentation() { const topic = $("#setup-topic")?.value.trim() || "", objective = $("#setup-objective")?.value.trim() || "", duration = Number($("#setup-duration")?.value); if (!topic || !objective || !Number.isInteger(duration) || duration < 1 || duration > 480) return notify(t("setupRequired"), true); const count = Number($("#setup-slides")?.value), instructions = $("#setup-instructions")?.value.trim(), scope = $("#setup-scope")?.value.trim(), multi = $("#setup-multidisciplinary")?.value, confirmed = Boolean($("#setup-scope-confirmed")?.checked), competence = Boolean($("#setup-competence")?.checked); if (!Number.isInteger(count) || count < 1 || count > 200 || !instructions || !scope || scope.length < 12 || !multi || !confirmed || (multi === "true" && !competence)) return notify(t("setupRequired"), true); const body = {target_slide_count:count, special_instructions:instructions, professional_scope:scope, is_multidisciplinary:multi === "true", confirmed_within_scope:confirmed, confirmed_multidisciplinary:competence, topic, objective, duration_minutes:duration, audience:$("#setup-audience").value, presentation_type:$("#setup-type").value, language:$("#setup-language").value}; const titleDetails = {presenter_name:"#setup-presenter-name", presenter_title:"#setup-presenter-title", organization:"#setup-organization", event_name:"#setup-event-name", venue:"#setup-venue", presentation_date:"#setup-presentation-date"}; Object.entries(titleDetails).forEach(([field, selector]) => { const value = $(selector)?.value.trim(); if (value) body[field] = value; }); if (state.project?.presentation) Object.entries(state.project.presentation.context).forEach(([field, value]) => { if (value !== null) body[field] = value; }); try { const response = await api(projectPath("/presentation/setup"), {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(body)}); saveProjectResponse(await response.json()); notify(t("changeSaved")); } catch (error) { notify(error.message, true); } }
async function submitScopeClarification() { const declared_role = $("#scope-declared-role")?.value.trim() || "", delivery_purpose = $("#scope-delivery-purpose")?.value.trim() || "", confirmed_within_scope = Boolean($("#scope-confirmed")?.checked); if (declared_role.length < 3 || delivery_purpose.length < 12 || !confirmed_within_scope) return notify(t("scopeRequired"), true); try { const response = await api(projectPath("/presentation/scope-clarification"), {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({declared_role, delivery_purpose, confirmed_within_scope})}); saveProjectResponse(await response.json()); notify(t("scopeSaved")); } catch (error) { notify(error.message, true); } }
async function startGeneration(action) {
  if (state.generationOperation || state.project?.workflow?.active_job) return notify(t("activeJob"), true);
  state.generationOperation = action;
  render();
  try {
    const response = await api(`/api/v1/projects/${endpoint(state.userId)}/${endpoint(state.projectId)}/${action}/jobs`, {showLoading:false, method:"POST"});
    await waitForJob(await response.json());
    await refreshProject(false);
  } catch (error) {
    notify(error.message, true);
    await refreshProject(false);
  } finally {
    state.generationOperation = null;
    render();
  }
}
async function startRegeneration(action, index = null, comments = "") { if (state.generationOperation || state.project?.workflow?.active_job) return notify(t("activeJob"), true); const blueprintComments = action === "blueprint" ? Object.fromEntries([...document.querySelectorAll('textarea[data-comment="blueprint"]')].map(node => [Number(node.dataset.index), node.value.trim()]).filter(([, value]) => value)) : null; state.generationOperation = action; render(); try { const path = action === "blueprint" ? `/api/v1/projects/${endpoint(state.userId)}/${endpoint(state.projectId)}/blueprint/regenerate/jobs` : `/api/v1/projects/${endpoint(state.userId)}/${endpoint(state.projectId)}/slides/${endpoint(index)}/regenerate/jobs`; const options = action === "slide" ? {showLoading:false, method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({comments})} : {showLoading:false, method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({comments_by_index:blueprintComments})}; const response = await api(path, options); await waitForJob(await response.json()); await refreshProject(false); notify(t("changeSaved")); } catch (error) { notify(error.message, true); await refreshProject(false); } finally { state.generationOperation = null; render(); } }
async function simpleAction(path) { try { const response = await api(projectPath(path), {method:"POST"}); saveProjectResponse(await response.json()); notify(path === "/resources/validate" ? t("resourcesValidatedContinue") : t("validationSaved")); } catch (error) { notify(error.message, true); } }
async function assessCoverage() { try { const response = await api(projectPath("/evidence-coverage"), {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({expected_revision:state.project.project_revision})}); saveProjectResponse(await response.json()); notify(t("coverageSaved")); } catch (error) { notify(error.message, true); } }
async function approveDiscussionTransfer() { const ids = [...document.querySelectorAll(".transfer-position:checked")].map(node => node.value); const uncertainties = $("#transfer-uncertainties").value.split("\n").map(value => value.trim()).filter(Boolean); try { const response = await api(projectPath("/discussion-transfer"), {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({expected_revision:state.project.project_revision, destination:$("#transfer-destination").value, content:$("#transfer-content").value, retained_position_ids:ids, uncertainties})}); saveProjectResponse(await response.json()); notify(t("transferSaved")); } catch (error) { notify(error.message, true); } }
async function reviewAction(button) { const kind = button.dataset.review, index = button.dataset.index, mode = button.dataset.mode, textarea = document.querySelector(`textarea[data-comment="${kind}"][data-index="${index}"]`), comments = textarea?.value || ""; if (mode === "regenerate") return startRegeneration("slide", index, comments); const path = kind === "blueprint" ? `/blueprint/items/${index}/${mode}` : `/slides/${index}/${mode}`; try { const response = await api(projectPath(path), {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({comments})}); saveProjectResponse(await response.json()); notify(mode === "reject" ? t("correctionSaved") : t("changeSaved")); } catch (error) { notify(error.message, true); } }
async function saveUserEdit(button) { const kind = button.dataset.edit, index = button.dataset.index, editor = button.closest(".content-editor"); const value = field => editor.querySelector(`[data-edit-field="${field}"]`)?.value || ""; const body = kind === "blueprint" ? {title:value("title"), objective:value("objective"), key_message:value("key_message"), supporting_source_ids:value("supporting_source_ids").split("\n").map(item => item.trim()).filter(Boolean), planned_visual:value("planned_visual"), content_origin:value("origin")} : {title:value("title"), objective:value("objective"), key_messages:value("key_messages").split("\n").map(item => item.trim()).filter(Boolean), content:value("content"), speaker_notes:value("speaker_notes"), content_origin:value("origin"), content_classification:value("content_classification")}; const path = kind === "blueprint" ? `/blueprint/items/${index}` : kind === "reformulation" ? `/slides/${index}/reformulation` : `/slides/${index}`; try { const response = await api(projectPath(path), {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify(body)}); saveProjectResponse(await response.json()); notify(t("changeSaved")); } catch (error) { notify(error.message, true); } }
async function slideReviewAction(button) { const index = button.dataset.index, action = button.dataset.slideAction, comments = document.querySelector(`textarea[data-comment="slide"][data-index="${index}"]`)?.value || ""; const path = `/slides/${index}${action === "comment" ? "/comments" : ""}`; try { const response = await api(projectPath(path), action === "comment" ? {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify({comments})} : {method:"DELETE"}); saveProjectResponse(await response.json()); notify(t("changeSaved")); } catch (error) { notify(error.message, true); } }
async function reviewSpeakerNote(button) { const approved = button.dataset.noteReview === "approve"; try { const response = await api(projectPath(`/slides/${button.dataset.index}/speaker-note/review`), {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({approved})}); saveProjectResponse(await response.json()); notify(t("changeSaved")); } catch (error) { notify(error.message, true); } }
