async function exportPptx() { try { const response = await api(`/presentations/${endpoint(state.userId)}/${endpoint(state.projectId)}/export/pptx`); const blob = await response.blob(), link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = `${currentPresentation()?.title || state.projectId}.pptx`; link.click(); URL.revokeObjectURL(link.href); } catch (error) { notify(error.message, true); } }
async function saveAgenda() { const items = $("#agenda-items").value.split("\n").map(item => item.trim()).filter(Boolean); const comments = $("#agenda-comments").value; try { const response = await api(projectPath("/agenda"), {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify({items, comments})}); saveProjectResponse(await response.json()); notify(t("changeSaved")); } catch (error) { notify(error.message, true); } }
