async function selectTemplate(payload) { if (!currentPresentation()) return notify(t("createPresentationFirst"), true); try { const response = await api(projectPath("/theme"), {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify({...payload, expected_revision: state.project.project_revision})}); saveProjectResponse(await response.json()); } catch (error) { notify(error.message, true); } }
async function savePresentationDetails() { const fields = {presenterName:"presenter_name", presenterTitle:"presenter_title", organization:"organization", eventName:"event_name", venue:"venue", presentationDate:"presentation_date"}; const body = Object.fromEntries(Object.entries(fields).map(([label, name]) => [name, document.querySelector(`[data-presentation-detail="${label}"]`)?.value || ""])); try { const response = await api(projectPath("/presentation/details"), {method:"PUT", headers:{"Content-Type":"application/json"}, body:JSON.stringify(body)}); saveProjectResponse(await response.json()); notify(t("changeSaved")); } catch (error) { notify(error.message, true); } }
function previewTemplate(theme) { const modal = $("#template-modal"), preview = $("#template-modal-preview"); $("#template-modal-title").textContent = t(`theme_${theme}`); preview.className = `template-large-preview ${theme}`; modal.hidden = false; }
async function uploadCustomTemplate() { const file = $("#template-file")?.files[0]; if (!file) return; if (!file.name.toLowerCase().endsWith(".pptx")) return notify(t("pptxOnly"), true); const form = new FormData(); form.append("file", file); if (!state.project?.prototype_declaration) return notify("Declare public/synthetic content first / Déclarez le contenu public ou synthétique.", true); form.append("prototype_declaration", state.project.prototype_declaration); form.append("external_processing_acknowledged", "true"); try { await api(`/users/${endpoint(state.userId)}/templates`, {method:"POST", body:form}); await loadTemplates(); await refreshProject(false); notify(t("templateAdded")); } catch (error) { notify(error.message, true); } }

